import otoken
import currency
tau_price_in_cents = Variable()
frozen = Variable()
cost_enabled = Variable()
operator = Hash(default_value=False)
price = Hash(default_value=2.56)
@construct
def seed():
    tau_price_in_cents.set(2.56)
    operator["list"] = ["96474552a93330e5af51d8a4ec22177d7b57eb1d776eeaa73a049a1830064542", "d3b192f8d65375e1c5e80c306a99c3ae7979a98f90c92776db7914cc1b3ec181", "0000803efd5df09c75c0c6670742db5074e5a011b829dfd8a0c50726d263a345"]
    operator[ctx.caller] = True
@export
def set_price(new_price: float):
    assert operator[ctx.caller] is True
    assert new_price < 1.2 * tau_price_in_cents.get() + 0.1
    assert new_price > 0
    price[ctx.caller] = new_price
@export
def calculate_price():
    assert frozen.get() != True
    oracle_count = 0
    total_price = 0
    for x in operator["list"]:
        oracle_count += 1
        total_price += price[x] 
    tau_price_in_cents.set(total_price / oracle_count)
@export
def replace_oracle(new_oracle: str):
    assert operator[ctx.caller] is True
    operator[ctx.caller] = False
    operator["list"] = operator["list"].remove(ctx.caller)
    operator["list"] = operator["list"].append(new_oracle)
    price[new_oracle] = tau_price_in_cents.get()
@export
def get_price():
    if cost_enabled.get() is True:
        otoken.transfer_from(1, ctx.this, ctx.caller)
    return tau_price_in_cents.get()
@export
def disperse_token():
    amount = otoken.balance_of(ctx.this) / len(operator["list"])
    for x in operator["list"]:
        otoken.transfer(amount, x)
    amount = currency.balance_of(ctx.this) / len(operator["list"])
    for x in operator["list"]:
        currency.transfer(amount, x)
@export
def is_frozen():
    return frozen.get()
@export 
def freeze_vote(vote: bool):
    assert operator[ctx.caller] is True
    operator[ctx.caller, "freeze"] = vote
@export
def freeze():
    oracle_count = 0
    yes_votes = 0
    for x in operator["list"]:
        oracle_count += 1
        if operator[x, "freeze"] is True:
            yes_votes += 1
    if yes_votes / oracle_count > 0.5:
        frozen.set(True)
        return True
    else:
        frozen.set(False)
        return False 
@export
def enable_cost():
    assert operator[ctx.caller] is True
    cost_enabled.set(True)
